class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

class Cart:
    def __init__(self):
        self.items = []

    def add(self, product):
        self.items.append(product)

    def total(self):
        total = 0
        for p in self.items:
            total += p.price
        return total

    def count(self):
        return len(self.items)


# 確かめるコード(消さない)
cart = Cart()
cart.add(Product("マウス", 2500))
cart.add(Product("キーボード", 6800))
print(cart.count(), cart.total())
